  Definition cmCH (x : Z) : Prop :=
    (C_AAC <= x < C_AAC + 8) \/ (C_AAREAS <= x < C_AAREAS + 8) \/ (a_areas A = [] /\ C_AHEAD <= x < C_AHEAD + 8) \/
    (C_ATAIL <= x < C_ATAIL + 8) \/ (C_AM <= x < C_AM + 8) \/ (C_AMC <= x < C_AMC + 8) \/
    (p <= x < p + 40) \/ (a_areas A <> [] /\ last (a_areas A) 0 + 8 <= x < last (a_areas A) 0 + 16).

